const claims = new WeakMap();
class ClaimsBuilder {
  constructor(payload = {}) {
    claims.set(this, structuredClone(payload));
  }
  setSubject(subject) {
    return claims.get(this).sub = subject, this;
  }
  setIssuer(issuer) {
    return claims.get(this).iss = issuer, this;
  }
  reset() {
    return claims.set(this, {}), this;
  }
}
const Signer_base = ClaimsBuilder;
class Signer extends Signer_base {
  #header = "none";
  setHeader(header) {
    return this.#header = header, this;
  }
  sign() {
    return `${this.#header}.${JSON.stringify(claims.get(this))}`;
  }
}
class Counter extends Signer {
  count() {
    return Object.keys(claims.get(this)).length;
  }
}
export { Signer, Counter };
